#include <inttypes.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>

static bool add_cents(int64_t left, int64_t right, int64_t *result)
{
    if (result == NULL) {
        return false;
    }
    if ((right > 0 && left > INT64_MAX - right) ||
        (right < 0 && left < INT64_MIN - right)) {
        return false;
    }
    *result = left + right;
    return true;
}

int main(void)
{
    int64_t total = 0;
    int64_t unchanged = 77;

    if (!add_cents(INT64_C(1250), INT64_C(2500), &total)) {
        return 1;
    }
    if (add_cents(INT64_MAX, INT64_C(1), &unchanged)) {
        return 2;
    }
    if (unchanged != 77) {
        return 3;
    }

    printf("total_cents=%" PRId64 "\n", total);
    printf("overflow_rejected=%s\n", unchanged == 77 ? "yes" : "no");
    return 0;
}

#include <stdio.h>

#ifndef APP_VERSION
#define APP_VERSION "dev"
#endif

#ifndef BUILD_PROFILE
#define BUILD_PROFILE "debug"
#endif

static void print_build_identity(void)
{
#if defined(__STDC_VERSION__)
    printf("c_standard_macro=%ld\n", (long)__STDC_VERSION__);
#else
    puts("c_standard_macro=pre-C99-or-unspecified");
#endif
    printf("app_version=%s\n", APP_VERSION);
    printf("build_profile=%s\n", BUILD_PROFILE);
}

int main(void)
{
    print_build_identity();
    return 0;
}
